import { WorkspaceSessionRenewal, validateWorkspaceSessionEnvelope } from './workspace-renewal.mjs';

const TOKEN_KEY='ltds-viewer-admin-token';
const NAV=[['dashboard','⌂','Dashboard'],['providers','⌁','Providers & nodes'],['diagnostics','▤','Diagnostics']];
const ACTIVE=new Set(['pending','admitted','initializing','uploading','committed','queued_upstream','running','ingesting','derivatives']);
const state={section:'dashboard',token:sessionStorage.getItem(TOKEN_KEY),adminSession:null,projects:[],datasets:[],tasks:[],providers:[],presets:[],outputs:[],shares:{},clientAccess:null,lastShareUrl:null,storage:null,ready:null,busy:false,projectQuery:'',selectedProjectId:null,expandedTaskId:null,selectedProviderId:null,taskDetails:{},logTimer:null};
const content=document.querySelector('#workspace-content'),shell=document.querySelector('#workspace'),modal=document.querySelector('#workspace-modal'),modalContent=document.querySelector('#workspace-modal-content');
const workspaceController=window.opener&&!window.opener.closed?window.opener:null;
let workspaceRenewal=null;

const esc=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const badge=value=>`<span class="status ${esc(value)}">${esc(String(value||'unknown').replaceAll('_',' '))}</span>`;
const bytes=value=>{const number=Number(value);if(!Number.isFinite(number))return'Unavailable';if(!number)return'0 B';const units=['B','KB','MB','GB','TB'],index=Math.min(Math.floor(Math.log(number)/Math.log(1024)),4);return`${(number/1024**index).toFixed(index>1?1:0)} ${units[index]}`};
const dateTime=value=>value?new Date(value).toLocaleString():'Unavailable';
const duration=attempt=>{const start=Date.parse(attempt?.startedAt||attempt?.createdAt||''),end=Date.parse(attempt?.completedAt||attempt?.updatedAt||'');if(!Number.isFinite(start)||!Number.isFinite(end)||end<start)return'Unavailable';const total=Math.round((end-start)/1000),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m ${total%60}s`};
const available=value=>value===undefined||value===null||value===''?'Unavailable':esc(value);
const opts=(items,label='Select')=>`<option value="">${esc(label)}</option>${items.map(item=>`<option value="${esc(item.id)}">${esc(item.displayName||item.name||item.id)}</option>`).join('')}`;
const empty=message=>`<div class="empty-state">${esc(message)}</div>`;
const field=(label,name,attributes='')=>`<label><span>${esc(label)}</span><input name="${esc(name)}" ${attributes}></label>`;
const select=(label,name,options)=>`<label><span>${esc(label)}</span><select name="${esc(name)}" required>${options}</select></label>`;
const button=(action,id,label,primary=false,extra='')=>`<button class="${primary?'primary':'secondary'}-button" data-action="${esc(action)}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const card=(title,body,action='')=>`<article class="content-card"><div class="card-heading"><h2>${esc(title)}</h2>${action}</div>${body}</article>`;
const values=form=>Object.fromEntries(new FormData(form).entries());

function toast(message,bad=false){const element=document.querySelector('#workspace-toast');element.textContent=message;element.className=bad?'bad':'';element.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>element.style.display='none',4000)}
function responseError(message,status){const error=Error(message);error.status=status;return error}
function clearWorkspaceAuthorization(){workspaceRenewal?.dispose();workspaceRenewal=null;sessionStorage.removeItem(TOKEN_KEY);state.token=null;state.adminSession=null;clearInterval(state.logTimer);renderNav();access()}
async function api(path,{method='GET',body,headers={}}={}){const init={method,headers:{Authorization:`Bearer ${state.token}`,Accept:'application/json',...headers}};if(method!=='GET'&&!init.headers['Idempotency-Key'])init.headers['Idempotency-Key']=crypto.randomUUID();if(body!==undefined){init.headers['Content-Type']='application/json';init.body=JSON.stringify(body)}const response=await fetch(path,init);let payload;try{payload=await response.json()}catch{}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(response.status===403)throw responseError('Your current Viewer grant does not permit this action',403);if(!response.ok)throw responseError(payload?.message||payload?.error||`Request failed (${response.status})`,response.status);return payload}
async function mutate(path,options,message){if(state.busy)return;state.busy=true;try{const result=await api(path,options);toast(message);await load();return result}catch(error){toast(error.message,true)}finally{state.busy=false}}
function installWorkspaceSession(envelope){const checked=validateWorkspaceSessionEnvelope({...envelope,accessToken:envelope.accessToken||state.token});if(envelope.accessToken){state.token=envelope.accessToken;sessionStorage.setItem(TOKEN_KEY,state.token)}state.adminSession=checked.session;workspaceRenewal?.dispose();workspaceRenewal=new WorkspaceSessionRenewal({controllerWindow:workspaceController,envelope,accessToken:state.token,onSession:value=>{state.adminSession=value.session},onExpired:clearWorkspaceAuthorization});workspaceRenewal.start()}
async function redeemGrant(){const parts=location.pathname.split('/').filter(Boolean),grant=parts[0]==='workspace'&&parts[1]&&parts[1]!=='active'?decodeURIComponent(parts[1]):null;if(!grant)return false;const response=await fetch('/api/v1/admin-sessions/redeem',{method:'POST',headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})},body:JSON.stringify({grant})});let body;try{body=await response.json()}catch{body={}}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(!response.ok)throw responseError(body.error||`Grant redemption failed (${response.status})`,response.status);installWorkspaceSession(body);history.replaceState(null,'','/workspace');return true}
async function restoreWorkspaceSession(){if(!state.token)return false;const response=await fetch('/api/v1/admin-sessions/current',{headers:{Authorization:`Bearer ${state.token}`,Accept:'application/json'}});let body;try{body=await response.json()}catch{body={}}if(response.status===401){clearWorkspaceAuthorization();throw responseError('authorization_required',401)}if(!response.ok)throw responseError(body.error||`Session check failed (${response.status})`,response.status);installWorkspaceSession(body);return true}

function renderNav(){document.querySelector('#workspace-navigation').innerHTML=NAV.map(([id,icon,label])=>`<button class="nav-link ${state.section===id?'active':''}" data-section="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');document.querySelectorAll('.nav-link').forEach(link=>link.onclick=()=>{state.section=link.dataset.section;shell.classList.remove('nav-open');render()})}
function metric(label,value,description){return`<article class="metric-card"><p>${esc(label)}</p><strong>${available(value)}</strong><small>${esc(description)}</small></article>`}
function openModal(title,body,className=''){modal.className=`workspace-modal ${className}`;modalContent.innerHTML=`<div class="modal-heading"><div><p class="eyebrow">Viewer workspace</p><h2 id="workspace-modal-title">${esc(title)}</h2></div><button class="icon-button modal-close" aria-label="Close dialog">×</button></div>${body}`;modalContent.querySelector('.modal-close').onclick=()=>modal.close();modal.showModal()}

function dashboard(){const active=state.tasks.filter(task=>ACTIVE.has(task.latestAttempt?.status)).length,healthy=state.providers.filter(provider=>provider.enabled&&['healthy','ready'].includes(provider.runtimeHealth||provider.lastHealth)).length;return`<div class="metric-grid">${metric('Projects',state.projects.length,'Viewer projects')}${metric('Published outputs',state.outputs.filter(output=>output.status==='published').length,bytes(state.outputs.reduce((sum,output)=>sum+(+output.byteSize||0),0)))}${metric('Processing now',active,'Active pipeline work')}${metric('Provider nodes',`${healthy}/${state.providers.length}`,'Enabled and healthy')}</div><section class="project-workspace top-gap"><div class="project-toolbar"><label class="project-search"><span class="sr-only">Filter projects by name</span><input id="project-filter" type="search" value="${esc(state.projectQuery)}" placeholder="Search projects…" autocomplete="off"></label><button class="primary-button" data-action="new-project">New project</button></div><div id="project-list" class="project-list">${projectRows()}</div>${selectedProject()}</section>`}
function projectRows(){const query=state.projectQuery.trim().toLocaleLowerCase('en-US'),projects=state.projects.filter(project=>!query||project.displayName.toLocaleLowerCase('en-US').includes(query));if(!projects.length)return empty(query?'No projects match that name.':'No projects yet.');return projects.map(project=>{const tasks=state.tasks.filter(task=>task.projectId===project.id),datasets=state.datasets.filter(dataset=>dataset.projectId===project.id),running=tasks.filter(task=>ACTIVE.has(task.latestAttempt?.status)).length,published=tasks.filter(task=>task.status==='published').length,selected=project.id===state.selectedProjectId;return`<article class="project-row ${selected?'selected':''}" data-project-name="${esc(project.displayName.toLocaleLowerCase('en-US'))}"><button class="project-open" data-action="open-project" data-id="${esc(project.id)}" aria-expanded="${selected}"><span><strong>${esc(project.displayName)}</strong><small>${esc(project.description||'No description')}</small></span><span class="project-stat"><strong>${tasks.length}</strong><small>tasks</small></span><span class="project-stat"><strong>${running}</strong><small>running</small></span><span class="project-stat"><strong>${published}</strong><small>published</small></span><span class="project-stat"><strong>${datasets.length}</strong><small>datasets</small></span>${badge(project.status)}<span aria-hidden="true">›</span></button></article>`}).join('')}
function selectedProject(){const project=state.projects.find(item=>item.id===state.selectedProjectId);if(!project)return'';const tasks=state.tasks.filter(task=>task.projectId===project.id),datasets=state.datasets.filter(dataset=>dataset.projectId===project.id),readyDatasets=datasets.filter(dataset=>dataset.status==='finalized');return`<section class="project-detail" aria-label="${esc(project.displayName)} project"><div class="project-detail-heading"><div><button class="text-button" data-action="close-project">← All projects</button><p class="eyebrow">Project</p><h2>${esc(project.displayName)}</h2><p>${esc(project.description||'No project description.')}</p></div><div class="row-actions"><button class="secondary-button" data-action="project-import" data-id="${esc(project.id)}">Import</button><button class="primary-button" data-action="project-process" data-id="${esc(project.id)}" ${readyDatasets.length&&state.providers.some(provider=>provider.enabled)?'':'disabled'}>New task</button><button class="secondary-button" data-action="project-share" data-id="${esc(project.id)}">Share</button><button class="secondary-button danger-button" data-action="archive-project" data-id="${esc(project.id)}">Archive</button></div></div><div class="project-columns">${card('Tasks',`<div class="task-list">${tasks.map(taskPanel).join('')||empty('No tasks in this project yet.')}</div>`)}${card('Project datasets',`<form id="dataset-form" class="manage-form inline-form"><input type="hidden" name="projectId" value="${esc(project.id)}">${field('Dataset name','displayName','required maxlength="240"')}<button class="secondary-button">Create upload draft</button></form><div class="data-list top-gap">${datasets.map(dataset=>`<div class="manage-row"><div><strong>${esc(dataset.displayName)}</strong><small>${dataset.fileCount??0} files · ${bytes(dataset.byteSize)}</small></div>${badge(dataset.status)}<div class="row-actions">${dataset.status==='draft'?`<button class="secondary-button" data-action="upload-dataset" data-id="${esc(dataset.id)}">Upload</button>`:''}</div></div>`).join('')||empty('No datasets yet.')}</div>`)}</div></section>`}
function taskPanel(task){const attempt=task.latestAttempt||{},expanded=state.expandedTaskId===task.id,dataset=state.datasets.find(item=>item.id===task.datasetId),sourceImages=task.metrics?.sourceImageCount;return`<article class="task-panel ${expanded?'expanded':''}"><button class="task-summary" data-action="toggle-task" data-id="${esc(task.id)}" aria-expanded="${expanded}"><span class="task-chevron" aria-hidden="true">${expanded?'⌄':'›'}</span><span><strong>${esc(task.displayName)}</strong><small>${dateTime(task.createdAt)}</small></span><span class="task-summary-stat"><strong>${sourceImages??'—'}</strong><small>images</small></span><span class="task-summary-stat"><strong>${duration(attempt)}</strong><small>runtime</small></span>${badge(attempt.status||task.status)}</button>${expanded?taskDetail(task,dataset):''}</article>`}
function metricItem(label,value,unit=''){return`<div class="task-metric"><span>${esc(label)}</span><strong>${available(value)}${value===undefined||value===null||value===''?'':esc(unit)}</strong></div>`}
function taskDetail(task,dataset){const detail=state.taskDetails[task.id],attempt=detail?.attempt||task.latestAttempt||{},metrics=detail?.task?.metrics||task.metrics||{},storage=detail?.storage?.task,outputs=detail?.task?.outputs||state.outputs.filter(output=>output.taskId===task.id),sets=detail?.gcp?.sets||[];if(detail?.loading)return`<div class="task-detail">${empty('Loading authoritative task details…')}</div>`;return`<div class="task-detail"><div class="task-detail-grid"><section><h3>Processing summary</h3><div class="task-metrics">${metricItem('Average GSD',metrics.averageGsd,metrics.averageGsdUnit?` ${metrics.averageGsdUnit}`:'')}${metricItem('Surveyed area',metrics.surveyedArea,metrics.surveyedAreaUnit?` ${metrics.surveyedAreaUnit}`:'')}${metricItem('Source images',metrics.sourceImageCount)}${metricItem('Reconstructed points',metrics.reconstructedPointCount)}${metricItem('Georeferencing CRS',metrics.georeferencingCrs)}${metricItem('Processing duration',metrics.processingDurationMs==null?duration(attempt):durationFromMs(metrics.processingDurationMs))}${metricItem('Output availability',metrics.outputCount?`${metrics.outputCount} output${metrics.outputCount===1?'':'s'}`:null)}${metricItem('Task disk usage',metrics.taskDiskUsageBytes==null?(storage?.totalBytes===undefined?null:bytes(storage.totalBytes)):bytes(metrics.taskDiskUsageBytes))}</div><p class="form-note">Unavailable means the processing API did not provide an authoritative value.</p></section><section><h3>Task controls</h3><dl class="task-options"><div><dt>Dataset</dt><dd>${esc(dataset?.displayName||'Unavailable')}</dd></div><div><dt>Provider</dt><dd>${esc(state.providers.find(provider=>provider.id===attempt.providerId)?.displayName||'Unavailable')}</dd></div><div><dt>Preset</dt><dd>${esc(state.presets.find(preset=>preset.id===attempt.presetId)?.displayName||'Provider defaults')}</dd></div><div><dt>Status</dt><dd>${badge(metrics.processingStatus||attempt.status||task.status)}</dd></div></dl><div class="row-actions task-lifecycle">${button('edit-task',task.id,'Edit')}${activeTaskAction(task,attempt)}<button class="secondary-button danger-button" data-action="archive-task" data-id="${esc(task.id)}">Archive task</button></div></section></div>${gcpPanel(task,dataset,sets)}${outputPanel(task,attempt,outputs)}${logPanel(task,attempt,detail?.logs||[])}</div>`}
function durationFromMs(value){const total=Math.max(0,Math.round(Number(value)/1000)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m ${total%60}s`}
function activeTaskAction(task,attempt){if(ACTIVE.has(attempt.status))return button('cancel-attempt',attempt.id,'Cancel');if(['failed','cancelled'].includes(attempt.status))return button('retry-attempt',attempt.id,'Restart',true);if(attempt.providerId)return button('restart-task',task.id,'Restart',false);return''}
function gcpPanel(task,dataset,sets){return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Ground control points</h3><p>Import survey points for this task’s source dataset, then mark photo correspondences in task context.</p></div><span>${sets.reduce((sum,set)=>sum+(Number(set.pointCount)||0),0)} points</span></div><div class="gcp-layout"><form class="manage-form gcp-import-form" data-dataset-id="${esc(dataset?.id||'')}" data-task-id="${esc(task.id)}">${field('Set name','displayName','required maxlength="160"')}<label><span>Survey file</span><input name="file" type="file" accept=".csv,.geojson,.json" required></label><label><span>Format</span><select name="format" required><option value="emlid-all-columns-v1">Emlid all-columns CSV</option><option value="generic-csv-v1">Generic CSV v1</option><option value="generic-geojson-v1">Generic GeoJSON v1</option></select></label><button class="secondary-button">Preview GCP import</button><p class="form-note">For Emlid exports, the server derives the exact coordinate system and units from CS name. Review that provenance before import; ambiguous files are rejected instead of guessed.</p></form><div class="data-list">${sets.map(set=>`<div class="manage-row"><div><strong>${esc(set.displayName)}</strong><small>${set.pointCount} points · ${esc(set.crs||'CRS unavailable')}</small></div>${badge(set.sourceFormat)}<div></div></div>`).join('')||empty('No GCP sets imported.')}</div></div></section>`}
function outputPanel(task,attempt,outputs){return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Outputs and review</h3><p>Actions appear only when the API reports the corresponding artifact.</p></div></div><div class="data-list">${outputs.map(output=>`<div class="manage-row output-row"><div><strong>${esc(output.displayName||task.displayName)}</strong><small>${bytes(output.byteSize)} · ${output.assetCount??0} assets</small></div>${badge(output.status)}<div class="row-actions">${artifactActions(output)}${output.status==='published'?button('share-output',output.id,'Share'):''}</div></div>`).join('')||empty('No output is available yet.')}</div>${attempt.status==='ready_for_review'?`<div class="inline-review"><p>Processing is complete. Review the isolated result before publishing verified assets.</p><div class="row-actions">${button('open-review',attempt.id,'Open review')}${button('publish-attempt',attempt.id,'Review & publish',true)}</div></div>`:''}</section>`}
function artifactActions(output){const kinds=new Set(Array.isArray(output.assetKinds)?output.assetKinds:[]),items=[],reviewable=output.status==='ready'&&output.attemptId;if(output.downloadUrl&&kinds.size)items.push(`<a class="secondary-button link-button" href="${esc(output.downloadUrl)}">Download</a>`);if(reviewable&&['ortho','dsm','dtm'].some(kind=>kinds.has(kind)))items.push(button('open-review',output.attemptId,'Map'));if(reviewable&&['tiles','ept','glb'].some(kind=>kinds.has(kind)))items.push(button('open-review',output.attemptId,'3D model'));if(output.reportUrl&&kinds.has('report'))items.push(`<a class="secondary-button link-button" href="${esc(output.reportUrl)}">Report</a>`);return items.join('')}
function logPanel(task,attempt,logs){const running=ACTIVE.has(attempt.status),text=logs.map(log=>`[${log.createdAt||''}] ${String(log.level||'info').toUpperCase()} ${log.message||''}`).join('\n');return`<section class="task-subsection"><div class="subsection-heading"><div><h3>Task output</h3><p>${running?'Live tail refreshes every five seconds.':'Latest bounded log tail.'}</p></div><div class="row-actions"><button class="secondary-button" data-action="download-logs" data-id="${esc(task.id)}">Download tail</button><button class="secondary-button" data-action="fullscreen-logs" data-id="${esc(task.id)}">Fullscreen</button></div></div><pre class="log-tail" tabindex="0" aria-label="Latest task output">${esc(text||'No task output has been recorded.')}</pre></section>`}

const providerName=type=>type==='clusterodm'?'ClusterODM':type==='nodeodm'?'NodeODM':'Unavailable';
const optionValue=value=>value===undefined||value===null?'Unavailable':typeof value==='string'?value:JSON.stringify(value);
function providers(){return`<div class="section-heading"><div><p class="eyebrow">Infrastructure</p><h2>Providers & nodes</h2><p>Add an endpoint once; Viewer probes and identifies the supported processing engine.</p></div><button class="primary-button" data-action="manage-providers">Manage nodes</button></div><div class="provider-summary">${state.providers.map(provider=>`<button class="provider-card" data-action="open-provider" data-id="${esc(provider.id)}"><span><strong>${esc(provider.displayName)}</strong><small>${providerName(provider.type)} · concurrency ${provider.admissionLimit}</small></span>${badge(provider.runtimeHealth||provider.lastHealth||'not probed')}</button>`).join('')||empty('No providers configured.')}</div>`}
function providerModal(selectedId=state.selectedProviderId){state.selectedProviderId=selectedId==='__new__'?'__new__':selectedId||state.providers[0]?.id||'__new__';const selected=state.providers.find(provider=>provider.id===state.selectedProviderId);openModal('Providers & nodes',`<div class="provider-master-detail"><aside><button class="secondary-button provider-add" data-action="provider-new">+ Add node</button><div class="provider-list">${state.providers.map(provider=>`<button class="provider-list-item ${provider.id===state.selectedProviderId?'active':''}" data-action="select-provider" data-id="${esc(provider.id)}"><span><strong>${esc(provider.displayName)}</strong><small>${esc(provider.endpoint)}</small></span>${badge(provider.runtimeHealth||provider.lastHealth||'unknown')}</button>`).join('')||empty('No nodes yet.')}</div></aside><section>${selected?providerDetail(selected):providerForm()}</section></div>`,'wide-modal');bindModalActions()}
function providerDetail(provider){const capabilities=provider.capabilities||{},options=Array.isArray(capabilities.options)?capabilities.options:[];return`<div class="provider-detail"><p class="eyebrow">Detected ${providerName(provider.type)}</p><h3>${esc(provider.displayName)}</h3><dl class="detail-list"><div><dt>Endpoint</dt><dd>${esc(provider.endpoint)}</dd></div><div><dt>API token</dt><dd>${provider.credential?.mode==='none'?'Not required':provider.credential?.configured?'Configured · hidden':'Not configured'}</dd></div><div><dt>Detected engine</dt><dd>${providerName(capabilities.providerType||provider.type)}</dd></div><div><dt>API version</dt><dd>${available(capabilities.apiVersion)}</dd></div><div><dt>Processing engine</dt><dd>${available(capabilities.engine)} · ${available(capabilities.engineVersion)}</dd></div><div><dt>Queue</dt><dd>${capabilities.taskQueueCount??'Unavailable'} queued · ${capabilities.maxParallelTasks??'Unavailable'} upstream slots</dd></div><div><dt>Viewer admission</dt><dd>${provider.admissionLimit} concurrent job${provider.admissionLimit===1?'':'s'}</dd></div><div><dt>Runtime health</dt><dd>${badge(provider.runtimeHealth||provider.lastHealth||'not probed')}</dd></div><div><dt>Options</dt><dd>${options.length} detected</dd></div></dl>${options.length?`<section class="provider-options" aria-label="Detected processing options"><h4>Processing options</h4><div class="provider-option-list">${options.slice(0,100).map(option=>`<div class="provider-option"><span><strong>${esc(option.name)}</strong><small>${esc(option.type||'unknown')}</small></span><code>${esc(optionValue(option.value))}</code></div>`).join('')}</div>${options.length>100?`<p class="form-note">Showing the first 100 of ${options.length} options.</p>`:''}</section>`:''}<div class="row-actions">${button('probe-provider',provider.id,'Re-probe')}${button('toggle-provider',provider.id,provider.enabled?'Disable':'Enable',!provider.enabled,`data-enabled="${!provider.enabled}"`)}</div><p class="form-note">Secrets are write-only and are never returned by the Viewer API. Engine type and capabilities come only from a successful endpoint probe.</p></div>`}
function providerForm(){return`<form id="provider-form" class="manage-form">${field('Node label','displayName','required maxlength="240"')}${field('HTTPS endpoint','endpoint','required type="url" placeholder="https://odm.example.com"')}${field('API token (if required)','token','type="password" autocomplete="new-password"')}<button class="primary-button">Detect & add node</button><p class="form-note">Viewer probes /info and /options, detects NodeODM or ClusterODM, and rejects unsupported or ambiguous endpoints. If supplied, the token is submitted once and is never displayed.</p></form>`}

function diagnostics(){const spaces=state.storage?.storage||{},trash=state.storage?.trash?.items||state.storage?.trash||[],lifecycle=state.ready?.lifecycle||[];return`<div class="metric-grid">${Object.entries(spaces).map(([key,item])=>metric(key,bytes(item.usedBytes),`${bytes(item.availableBytes)} available`)).join('')}${metric('Processing worker',state.ready?.worker?.live?'Live':'Unavailable','Queue and worker health')}${metric('Platform',state.ready?.ok?'Ready':'Attention needed','Aggregated readiness')}</div><div class="diagnostic-grid top-gap">${card('Queue & provider health',`<div class="data-list">${state.providers.map(provider=>`<div class="manage-row"><div><strong>${esc(provider.displayName)}</strong><small>${esc(provider.endpoint)}</small></div>${badge(provider.runtimeHealth||provider.lastHealth||'unknown')}<div></div></div>`).join('')||empty('No providers configured.')} ${lifecycle.map(item=>`<div class="manage-row"><div><strong>${esc(item.status)}</strong><small>Storage lifecycle operations</small></div><strong>${item.count}</strong><div></div></div>`).join('')}</div>`)}${card('Storage trash & recovery',`<div class="data-list">${trash.map(item=>`<div class="manage-row"><div><strong>${esc(item.displayName||item.entityType)}</strong><small>${esc(item.entityType)} · ${bytes(item.byteSize)}</small></div>${badge('trash')}<div>${button('restore-trash',item.id,'Restore')}</div></div>`).join('')||empty('Trash is empty.')}</div>`)}</div>`}

function render(){clearInterval(state.logTimer);renderNav();document.querySelector('#page-title').textContent=NAV.find(item=>item[0]===state.section)?.[2]||'Dashboard';content.innerHTML=({dashboard,providers,diagnostics}[state.section]||dashboard)();bind();if(state.expandedTaskId){const task=state.tasks.find(item=>item.id===state.expandedTaskId);if(ACTIVE.has(task?.latestAttempt?.status))state.logTimer=setInterval(()=>refreshTaskDetails(task.id,true),5000)}}
function bind(){content.querySelectorAll('[data-section]').forEach(element=>element.onclick=()=>{state.section=element.dataset.section;render()});content.querySelectorAll('[data-action]').forEach(element=>element.onclick=()=>action(element));const filter=content.querySelector('#project-filter');if(filter)filter.oninput=()=>{state.projectQuery=filter.value;const query=state.projectQuery.trim().toLocaleLowerCase('en-US');content.querySelectorAll('[data-project-name]').forEach(row=>row.hidden=Boolean(query&&!row.dataset.projectName.includes(query)))};const datasetForm=content.querySelector('#dataset-form');if(datasetForm)datasetForm.onsubmit=event=>{event.preventDefault();mutate('/api/v1/datasets',{method:'POST',body:values(datasetForm)},'Dataset draft created')};content.querySelectorAll('.gcp-import-form').forEach(form=>form.onsubmit=importGcp)}
async function action(element){const action=element.dataset.action,id=element.dataset.id;if(action==='new-project')return newProjectModal();if(action==='open-project'){state.selectedProjectId=id;state.expandedTaskId=null;return render()}if(action==='close-project'){state.selectedProjectId=null;state.expandedTaskId=null;return render()}if(action==='archive-project')return mutate(`/api/v1/projects/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Project archived');if(action==='project-import'||action==='upload-dataset')return importModal(action==='upload-dataset'?null:id,action==='upload-dataset'?id:null);if(action==='project-process')return processModal(id);if(action==='project-share')return shareModal(id);if(action==='toggle-task'){if(state.expandedTaskId===id){state.expandedTaskId=null;return render()}state.expandedTaskId=id;state.taskDetails[id]={loading:true};render();return refreshTaskDetails(id)}if(action==='edit-task')return editTask(id);if(action==='archive-task')return mutate(`/api/v1/tasks/${encodeURIComponent(id)}/archive`,{method:'POST',body:{}},'Task archived');if(action==='cancel-attempt'||action==='retry-attempt')return mutate(`/api/v1/attempts/${encodeURIComponent(id)}/${action.startsWith('cancel')?'cancel':'retry'}`,{method:'POST',body:{}},action.startsWith('cancel')?'Attempt cancelled':'Task restarted');if(action==='restart-task')return restartTask(id);if(action==='open-review')return openReview(id);if(action==='publish-attempt')return publishAttempt(id);if(action==='share-output')return shareModal(state.selectedProjectId,id);if(action==='download-logs')return downloadLogs(id);if(action==='fullscreen-logs')return fullscreenLogs(id);if(action==='manage-providers')return providerModal();if(action==='open-provider')return providerModal(id);if(action==='restore-trash')return mutate(`/api/v1/storage/trash/${encodeURIComponent(id)}/restore`,{method:'POST',body:{}},'Item restored')}

async function refreshTaskDetails(taskId,quiet=false){const task=state.tasks.find(item=>item.id===taskId),attemptId=task?.latestAttempt?.id;if(!task)return;const requests=[api(`/api/v1/tasks/${encodeURIComponent(taskId)}`),api(`/api/v1/tasks/${encodeURIComponent(taskId)}/storage?limit=100`),api(`/api/v1/datasets/${encodeURIComponent(task.datasetId)}/gcp-sets`)];if(attemptId)requests.push(api(`/api/v1/attempts/${encodeURIComponent(attemptId)}?logLimit=100`));const results=await Promise.allSettled(requests);state.taskDetails[taskId]={task:results[0].value?.task||task,storage:results[1].value||null,gcp:results[2].value||{sets:[]},attempt:results[3]?.value?.attempt||task.latestAttempt,logs:(results[3]?.value?.logs||[]).slice(-100)};if(state.expandedTaskId===taskId){render();if(!quiet)document.querySelector(`[data-action="toggle-task"][data-id="${CSS.escape(taskId)}"]`)?.focus()}}
function newProjectModal(){openModal('Create project',`<form id="project-form" class="manage-form">${field('Project name','displayName','required maxlength="240"')}${field('Description','description','maxlength="1000"')}<button class="primary-button">Create project</button></form>`);modalContent.querySelector('#project-form').onsubmit=event=>{event.preventDefault();modal.close();mutate('/api/v1/projects',{method:'POST',body:values(event.currentTarget)},'Project created')}}
function importModal(projectId,datasetId){const project=state.projects.find(item=>item.id===(projectId||state.datasets.find(dataset=>dataset.id===datasetId)?.projectId)),drafts=state.datasets.filter(dataset=>dataset.projectId===project?.id&&dataset.status==='draft');openModal(`Import into ${project?.displayName||'project'}`,`<div class="import-choice" role="tablist" aria-label="Import source"><button class="import-tab active" data-import-tab="device">This device</button><button class="import-tab" data-import-tab="server">Server import folder</button></div><section data-import-panel="device"><form id="upload-form" class="manage-form">${select('Draft dataset','datasetId',opts(drafts,'Select a draft'))}<label><span>Artifact role</span><select name="processingRole"><option value="auto">Detect automatically</option><option value="image">Source imagery</option><option value="provider_input">Model / orthophoto / point cloud</option><option value="gcp_source">GCP source</option></select></label>${field('Files','files','required type="file" multiple')}<button class="primary-button">Upload or resume</button><progress id="upload-progress" value="0" max="100"></progress></form><p class="form-note">Browser uploads are limited to 128 files, 64 MB each, and 256 MB total.</p></section><section data-import-panel="server" hidden><form id="server-import-form" class="manage-form"><input type="hidden" name="projectId" value="${esc(project?.id||'')}">${field('Task name','taskDisplayName','required maxlength="240"')}${field('Folder or backup ZIP','sourceRelativePath','required placeholder="incoming/task-folder or task.zip"')}<button class="primary-button">Queue import</button></form><p class="form-note">Select a path inside the managed server import folder. The server validates and adopts the supported artifacts after confirmation.</p></section>`);modalContent.querySelectorAll('[data-import-tab]').forEach(tab=>tab.onclick=()=>{modalContent.querySelectorAll('[data-import-tab]').forEach(item=>item.classList.toggle('active',item===tab));modalContent.querySelectorAll('[data-import-panel]').forEach(panel=>panel.hidden=panel.dataset.importPanel!==tab.dataset.importTab)});const upload=modalContent.querySelector('#upload-form');if(datasetId)upload.elements.datasetId.value=datasetId;upload.onsubmit=event=>{event.preventDefault();uploadFiles(upload)};modalContent.querySelector('#server-import-form').onsubmit=event=>{event.preventDefault();modal.close();mutate('/api/v1/processing/webodm-task-imports',{method:'POST',body:values(event.currentTarget),headers:{'Idempotency-Key':crypto.randomUUID()}},'Server-folder import queued')}}
function processModal(projectId){const ready=state.datasets.filter(dataset=>dataset.projectId===projectId&&dataset.status==='finalized'),enabled=state.providers.filter(provider=>provider.enabled);openModal('Start processing task',`<form id="job-form" class="manage-form"><input type="hidden" name="projectId" value="${esc(projectId)}">${select('Finalized dataset','datasetId',opts(ready))}${select('Enabled provider','providerId',opts(enabled))}${select('Preset (optional)','presetId',opts(state.presets,'Provider defaults'))}${field('Task name','taskDisplayName','required maxlength="240"')}<button class="primary-button">Submit task</button></form>`);modalContent.querySelector('#job-form').onsubmit=event=>{event.preventDefault();const body=values(event.currentTarget);body.submissionId=crypto.randomUUID();body.options={};if(!body.presetId)delete body.presetId;modal.close();mutate('/api/v1/task-submissions',{method:'POST',body},'Processing task submitted')}}
async function editTask(id){const task=state.tasks.find(item=>item.id===id),displayName=prompt('Task name',task?.displayName||'');if(!displayName)return;const description=prompt('Description',task?.description||'');await mutate(`/api/v1/tasks/${encodeURIComponent(id)}`,{method:'PATCH',body:{displayName,description}},'Task updated')}
async function restartTask(id){const task=state.tasks.find(item=>item.id===id),attempt=task?.latestAttempt;if(!attempt?.providerId)return toast('The task has no prior provider configuration',true);return mutate(`/api/v1/tasks/${encodeURIComponent(id)}/attempts`,{method:'POST',body:{providerId:attempt.providerId,...(attempt.presetId?{presetId:attempt.presetId}:{}),options:attempt.options||{}}},'New processing attempt queued')}
async function openReview(id){try{const result=await api(`/api/v1/attempts/${encodeURIComponent(id)}/review-sessions`,{method:'POST',body:{}});window.open(result.embedUrl,'_blank','noopener')}catch(error){toast(error.message,true)}}
async function publishAttempt(id){try{const result=await api(`/api/v1/attempts/${encodeURIComponent(id)}/review-sessions`,{method:'POST',body:{}});if(confirm(`Publish the verified ${result.assetKinds.join(', ')} assets?`))await mutate(`/api/v1/attempts/${encodeURIComponent(id)}/publish`,{method:'POST',body:{selectedAssetKinds:result.assetKinds}},'Output published')}catch(error){toast(error.message,true)}}
async function importGcp(event){event.preventDefault();const form=event.currentTarget,file=form.elements.file.files[0];if(!file)return;const format=form.elements.format.value,contentText=await file.text(),previewPath=`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import-preview`;let declarations,preview;try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText}})}catch(error){if(format!=='emlid-all-columns-v1'||!error.message.includes('units are not explicit'))return toast(error.message,true);const unit=prompt('This file does not declare projected units. Enter m or ftUS to continue:');if(!['m','ftUS'].includes(unit))return toast('GCP import cancelled; choose m or ftUS only',true);declarations={linearUnit:unit};try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText,declarations}})}catch(retryError){return toast(retryError.message,true)}}const body={displayName:form.elements.displayName.value,format,fileName:file.name,content:contentText,...(declarations?{declarations}:{})};openModal('Confirm GCP import',`<div class="gcp-preview"><p>The API parsed <strong>${preview.pointCount}</strong> points. Confirm this authoritative mapping before writing the set.</p><dl class="detail-list"><div><dt>Point identifier</dt><dd>${esc(preview.columns?.id||'Unavailable')}</dd></div><div><dt>Survey coordinates</dt><dd>${esc((preview.columns?.authoritative||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Cross-check only</dt><dd>${esc((preview.columns?.crossCheck||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Coordinate system</dt><dd>${esc(preview.provenance?.coordinateSystem||'Unavailable')}</dd></div><div><dt>Vertical datum</dt><dd>${esc(preview.provenance?.verticalDatum||'Unavailable')}</dd></div><div><dt>Linear unit</dt><dd>${esc(preview.provenance?.linearUnit||'Unavailable')}</dd></div></dl>${(preview.warnings||[]).map(warning=>`<p class="form-note">Warning: ${esc(warning)}</p>`).join('')}<div class="row-actions"><button class="secondary-button modal-cancel">Cancel</button><button class="primary-button gcp-confirm">Confirm import</button></div></div>`);modalContent.querySelector('.modal-cancel').onclick=()=>modal.close();modalContent.querySelector('.gcp-confirm').onclick=async()=>{modal.close();await mutate(`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import`,{method:'POST',body:{...body,confirmationToken:preview.confirmationToken}},'GCP set imported');await refreshTaskDetails(form.dataset.taskId)}}

function shareModal(projectId,onlyOutputId=null){const project=state.projects.find(item=>item.id===projectId),taskIds=new Set(state.tasks.filter(task=>task.projectId===projectId).map(task=>task.id)),published=state.outputs.filter(output=>output.status==='published'&&taskIds.has(output.taskId)&&(!onlyOutputId||output.id===onlyOutputId)),access=state.clientAccess,portalProjects=access?.projects||[],associations=access?.associations||[],grants=access?.grants||[];openModal(`Share ${project?.displayName||'project'}`,`<div class="share-columns">${access?card('Authenticated client access',`<form id="client-grant-form" class="manage-form"><label><span>Client Portal project</span><select name="projectId" required><option value="">Select client project</option>${portalProjects.map(item=>`<option value="${esc(item.id)}" data-account-id="${esc(item.accountId||item.account_id||'')}">${esc(item.clientName||item.client_name||'Client')} — ${esc(item.name||item.projectName||item.project_name||item.id)}</option>`).join('')}</select></label><label><span>Access scope</span><select name="scopeType"><option value="project">Entire project</option><option value="task">One published task</option></select></label><label class="client-task-field" hidden><span>Published task</span><select name="associationId"><option value="">Select a task</option>${associations.map(item=>`<option value="${esc(item.id)}" data-project-id="${esc(item.projectId||item.project_id||'')}">${esc(item.modelTitle||item.model_title||item.displayName||item.id)}</option>`).join('')}</select></label>${field('Expiry (optional)','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="includeFuturePublished" checked> Include future published tasks</label><label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><button class="primary-button">Grant client access</button></form><div class="data-list top-gap">${grants.map(grant=>`<div class="manage-row"><div><strong>${esc(grant.clientName||grant.client_name||grant.accountId)}</strong><small>${esc(grant.projectName||grant.project_name||grant.projectId)}</small></div>${badge(grant.status||'active')}<div>${(grant.status||'active')==='active'?button('revoke-client-grant',grant.id,'Revoke'):''}</div></div>`).join('')||empty('No authenticated client grants.')}</div>`):card('Authenticated client access',empty('Your current grant does not include client-access management.'))}<div>${state.lastShareUrl?card('New public link — copy now',`<div class="share-result"><input readonly value="${esc(state.lastShareUrl)}"><button class="primary-button" data-action="copy-share" data-url="${esc(state.lastShareUrl)}">Copy</button></div>`):''}${published.map(output=>card(output.displayName||'Published task',`<form class="manage-form share-form" data-output-id="${esc(output.id)}">${field('Link label','label','maxlength="120"')}${field('Optional password','password','type="password" minlength="8" autocomplete="new-password"')}${field('Expiry','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><button class="primary-button">Create public link</button></form><div class="data-list top-gap">${(state.shares[output.id]||[]).map(share=>`<div class="manage-row"><div><strong>${esc(share.label||'Public link')}</strong><small>${share.hasPassword?'Password protected':'No password'}</small></div>${badge(share.revokedAt?'revoked':'active')}<div>${!share.revokedAt?button('revoke-share',share.id,'Revoke'):''}</div></div>`).join('')||empty('No public links.')}</div>`)).join('')||card('Published tasks',empty('No published task is available to share.'))}</div></div>`,'wide-modal');bindShareModal()}
function bindShareModal(){const grantForm=modalContent.querySelector('#client-grant-form');if(grantForm){const sync=()=>{const task=grantForm.elements.scopeType.value==='task',projectId=grantForm.elements.projectId.value;grantForm.querySelector('.client-task-field').hidden=!task;grantForm.elements.associationId.required=task;grantForm.elements.includeFuturePublished.disabled=task;if(task)grantForm.elements.includeFuturePublished.checked=false;for(const option of grantForm.elements.associationId.options){if(!option.value)continue;option.hidden=option.dataset.projectId!==projectId;option.disabled=option.hidden}if(grantForm.elements.associationId.selectedOptions[0]?.disabled)grantForm.elements.associationId.value=''};grantForm.elements.scopeType.onchange=sync;grantForm.elements.projectId.onchange=sync;sync();grantForm.onsubmit=event=>{event.preventDefault();const selected=grantForm.elements.projectId.selectedOptions[0],scopeType=grantForm.elements.scopeType.value,body={grant:{accountId:selected.dataset.accountId,projectId:selected.value,scopeType,associationId:scopeType==='task'?grantForm.elements.associationId.value:null,includeFuturePublished:scopeType==='project'&&grantForm.elements.includeFuturePublished.checked,expiresAt:grantForm.elements.expiresAt.value?new Date(grantForm.elements.expiresAt.value).toISOString():null,permissions:{measure:grantForm.elements.measure.checked,cameras:grantForm.elements.cameras.checked,download:grantForm.elements.download.checked}}};modal.close();mutate('/api/v1/workspace/client-grants',{method:'POST',body},'Client access granted')}}modalContent.querySelectorAll('.share-form').forEach(form=>form.onsubmit=async event=>{event.preventDefault();const input=values(form),body={label:input.label,expiresAt:input.expiresAt?new Date(input.expiresAt).toISOString():null,permissions:{view:true,measure:form.elements.measure.checked,cameras:form.elements.cameras.checked,download:form.elements.download.checked}};if(input.password)body.password=input.password;try{const result=await api(`/api/v1/processing/outputs/${encodeURIComponent(form.dataset.outputId)}/shares`,{method:'POST',body});state.lastShareUrl=result.viewUrl;await navigator.clipboard?.writeText(result.viewUrl);toast('Public link created and copied');await load();shareModal(state.selectedProjectId)}catch(error){toast(error.message,true)}});modalContent.querySelectorAll('[data-action="revoke-client-grant"]').forEach(element=>element.onclick=()=>{const reason=prompt('Reason for revoking this client access');if(reason){modal.close();mutate('/api/v1/workspace/client-grants',{method:'DELETE',body:{grantId:element.dataset.id,reason}},'Client access revoked')}});modalContent.querySelectorAll('[data-action="revoke-share"]').forEach(element=>element.onclick=()=>{modal.close();mutate(`/api/v1/processing/shares/${encodeURIComponent(element.dataset.id)}`,{method:'DELETE',body:{}},'Link revoked')});modalContent.querySelectorAll('[data-action="copy-share"]').forEach(element=>element.onclick=async()=>{await navigator.clipboard.writeText(element.dataset.url);toast('Link copied')})}
function bindModalActions(){modalContent.querySelectorAll('[data-action]').forEach(element=>element.onclick=()=>{const action=element.dataset.action,id=element.dataset.id;if(action==='provider-new')return providerModal('__new__');if(action==='select-provider')return providerModal(id);if(action==='probe-provider'){modal.close();return mutate(`/api/v1/processing/providers/${encodeURIComponent(id)}/capabilities/probe`,{method:'POST',body:{}},'Provider capabilities refreshed')}if(action==='toggle-provider'){modal.close();return mutate(`/api/v1/processing/providers/${encodeURIComponent(id)}`,{method:'PATCH',body:{enabled:element.dataset.enabled==='true'}},'Provider updated')}});const form=modalContent.querySelector('#provider-form');if(form)form.onsubmit=async event=>{event.preventDefault();if(state.busy)return;const input=values(form),submit=form.querySelector('button[type="submit"],button:not([type])'),body={displayName:input.displayName,endpoint:input.endpoint};if(input.token)body.credential={token:input.token};state.busy=true;submit.disabled=true;submit.textContent='Detecting…';try{const result=await api('/api/v1/processing/providers',{method:'POST',body});toast(`${providerName(result.detection?.providerType)} detected and added`);modal.close();await load();providerModal(result.provider.id)}catch(error){toast(error.message,true);submit.disabled=false;submit.textContent='Detect & add node'}finally{state.busy=false}}}

function logText(taskId){return(state.taskDetails[taskId]?.logs||[]).map(log=>`[${log.createdAt||''}] ${String(log.level||'info').toUpperCase()} ${log.message||''}`).join('\n')||'No task output has been recorded.'}
function downloadLogs(taskId){const task=state.tasks.find(item=>item.id===taskId),link=document.createElement('a');link.href=URL.createObjectURL(new Blob([logText(taskId)],{type:'text/plain'}));link.download=`${(task?.displayName||'task').replace(/[^a-z0-9_-]+/gi,'-')}-log-tail.txt`;link.click();URL.revokeObjectURL(link.href)}
function fullscreenLogs(taskId){openModal('Task output',`<pre class="log-tail fullscreen-log" tabindex="0">${esc(logText(taskId))}</pre>`,'wide-modal')}
async function digest(buffer){return[...new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))].map(value=>value.toString(16).padStart(2,'0')).join('')}
async function uploadFiles(form){const files=[...form.elements.files.files],datasetId=form.elements.datasetId.value,role=form.elements.processingRole.value,total=files.reduce((sum,file)=>sum+file.size,0),progress=form.querySelector('progress');if(!files.length||files.length>128||files.some(file=>file.size>64*1024**2)||total>256*1024**2)return toast('Browser upload limit exceeded (128 files, 64 MB each, 256 MB total); use the server import folder for larger artifacts',true);state.busy=true;try{let preparedCount=0;const prepared=[];for(let index=0;index<files.length;index++){const buffer=await files[index].arrayBuffer();prepared.push({file:files[index],spec:{id:`file-${index}`,relativePath:files[index].webkitRelativePath||files[index].name,byteSize:files[index].size,sha256:await digest(buffer),contentType:files[index].type||'application/octet-stream',processingRole:role}});progress.value=Math.round(++preparedCount/files.length*15)}const created=await api(`/api/v1/datasets/${encodeURIComponent(datasetId)}/uploads`,{method:'POST',body:{files:prepared.map(item=>item.spec)}}),upload=created.upload,token=created.uploadToken;sessionStorage.setItem('ltds-viewer-upload',JSON.stringify({datasetId,uploadId:upload.id,manifest:prepared.map(item=>item.spec)}));let sent=0;for(const item of prepared){const remote=upload.files.find(file=>file.id===item.spec.id),missing=new Set(remote.missingChunks);for(let index=0;index<remote.chunkCount;index++){const start=index*upload.chunkSize,end=Math.min(start+upload.chunkSize,item.file.size);if(missing.has(index)){const chunk=await item.file.slice(start,end).arrayBuffer(),response=await fetch(`/api/v1/admin/uploads/${encodeURIComponent(upload.id)}/files/${encodeURIComponent(item.spec.id)}/chunks/${index}`,{method:'PUT',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/octet-stream','X-Upload-Token':token,'X-Chunk-SHA256':await digest(chunk)},body:chunk});if(!response.ok)throw Error(`Chunk upload failed (${response.status})`)}sent+=end-start;progress.value=15+Math.round(sent/Math.max(total,1)*80)}}await api(`/api/v1/admin/uploads/${encodeURIComponent(upload.id)}/finalize`,{method:'POST',body:{uploadToken:token}});sessionStorage.removeItem('ltds-viewer-upload');progress.value=100;modal.close();toast('Upload finalized; processing will index the dataset');await load()}catch(error){toast(`${error.message}. Reselect the same files to resume.`,true)}finally{state.busy=false}}

async function pagedApi(path,key){const items=[],seen=new Set();let cursor=null;do{const separator=path.includes('?')?'&':'?',page=await api(`${path}${separator}limit=100${cursor?`&cursor=${encodeURIComponent(cursor)}`:''}`);items.push(...(page[key]||[]));cursor=page.nextCursor||null;if(cursor&&seen.has(cursor))throw Error(`Pagination cursor repeated for ${key}`);if(cursor)seen.add(cursor)}while(cursor);return{[key]:items}}
async function load(){const requests=[pagedApi('/api/v1/projects','projects'),pagedApi('/api/v1/datasets','datasets'),pagedApi('/api/v1/tasks','tasks'),api('/api/v1/processing/providers?limit=100'),api('/api/v1/processing/presets'),pagedApi('/api/v1/processing/outputs','outputs'),api('/api/v1/storage?limit=100'),api('/api/v1/processing/ready'),api('/api/v1/workspace/client-grants')],results=await Promise.allSettled(requests);if(!state.token)return access();[state.projects,state.datasets,state.tasks,state.providers,state.presets,state.outputs,state.storage,state.ready,state.clientAccess]=[results[0].value?.projects||[],results[1].value?.datasets||[],results[2].value?.tasks||[],results[3].value?.providers||[],results[4].value?.presets||[],results[5].value?.outputs||[],results[6].value||null,results[7].value||null,results[8].value||null];if(state.selectedProjectId&&!state.projects.some(project=>project.id===state.selectedProjectId))state.selectedProjectId=null;const published=state.outputs.filter(output=>output.status==='published'),shareResults=await Promise.allSettled(published.map(output=>api(`/api/v1/processing/outputs/${encodeURIComponent(output.id)}/shares`)));state.shares=Object.fromEntries(published.map((output,index)=>[output.id,shareResults[index].value?.shares||[]]));const okay=state.ready?.ok===true;document.querySelector('#nav-health-dot').className=`health-dot ${okay?'good':'bad'}`;document.querySelector('#nav-health-label').textContent=okay?'Platform ready':'Attention needed';render()}
function access(){content.innerHTML='<div class="auth-state"><div><p class="eyebrow">Secure workspace</p><h2>Open Viewer from LTDS Operations</h2><p>This workspace reuses your Operations identity and has no separate login.</p></div></div>'}

